type QualitySeverity = "info" | "warning" | "blocking";
type QualityGateStatus = "passed" | "warning" | "failed";
type QualityGateMode = "off" | "warn" | "strict";
interface BaseQualityIssue {
    code: string;
    severity: QualitySeverity;
    message: string;
}
interface QualityRound {
    round: number;
    kind: string;
    status: "passed" | "warning" | "failed";
    summary?: string;
}
interface QualityArtifact {
    kind: string;
    label?: string;
    itemCount?: number;
}
interface UnifiedQualityReport<TIssue extends BaseQualityIssue = BaseQualityIssue> {
    issues: TIssue[];
    rounds: QualityRound[];
    artifacts: QualityArtifact[];
    qualityGateStatus: QualityGateStatus;
}

interface DocumentChunk {
    /** Deterministic ID: `${documentId}:${type}:${index}` */
    id: string;
    /** Source document ID */
    documentId: string;
    /** Chunk type for filtering */
    type: "carrier_info" | "named_insured" | "coverage" | "covered_reason" | "definition" | "endorsement" | "exclusion" | "condition" | "section" | "declaration" | "loss_history" | "premium" | "supplementary" | "location" | "vehicle" | "classification" | "financial" | "party" | "subjectivity" | "underwriting_condition";
    /** Human-readable text for embedding */
    text: string;
    /** Structured metadata for filtering */
    metadata: Record<string, string>;
}
interface ConversationTurn {
    id: string;
    conversationId: string;
    role: "user" | "assistant" | "tool";
    content: string;
    toolName?: string;
    toolResult?: string;
    timestamp: number;
}
interface ChunkFilter {
    documentId?: string;
    type?: DocumentChunk["type"];
    metadata?: Record<string, string>;
}
interface DocumentFilters {
    type?: "policy" | "quote";
    carrier?: string;
    insuredName?: string;
    policyNumber?: string;
    quoteNumber?: string;
}

interface DocumentStore {
    save(doc: InsuranceDocument): Promise<void>;
    get(id: string): Promise<InsuranceDocument | null>;
    query(filters: DocumentFilters): Promise<InsuranceDocument[]>;
    delete(id: string): Promise<void>;
}
interface MemoryStore {
    addChunks(chunks: DocumentChunk[]): Promise<void>;
    search(query: string, options?: {
        limit?: number;
        filter?: ChunkFilter;
    }): Promise<DocumentChunk[]>;
    addTurn(turn: ConversationTurn): Promise<void>;
    getHistory(conversationId: string, options?: {
        limit?: number;
    }): Promise<ConversationTurn[]>;
    searchHistory(query: string, conversationId?: string): Promise<ConversationTurn[]>;
}

